    34→
    35→    // Proxy all HTTPS traffic through the configured HTTPS proxy
    36→    if let Some(url) = proxy_config.https_url.as_ref() {
    37→        client_builder = client_builder.proxy(
    38→            reqwest::Proxy::https(url)
    39→                .change_context(ApiClientError::InvalidProxyConfiguration)
    40→                .attach_printable("HTTPS proxy configuration error")?
    41→                .no_proxy(proxy_exclusion_config.clone()),
    42→        );
    43→    }
    44→
    45→    // Proxy all HTTP traffic through the configured HTTP proxy
    46→    if let Some(url) = proxy_config.http_url.as_ref() {
    47→        client_builder = client_builder.proxy(
