ayload=?request.body, ?request);\n\n        let url = url::Url::parse(&request.url)\n            .change_context(ApiClientError::UrlParsingFailed)?;\n\n        let client = crate::services::client::create_client(\n            &state.conf.proxy,\n            request.certificate,\n            request.certificate_key,\n        )?;\n\n        let headers = request.headers.construct_header_map()?;\n        let metrics_tag = router_env::metric_attributes!((\n            consts::METRICS_HOST_TAG_NAME,\n            url.host_str().unwrap_or_default().to_owned()\n        ));\n\n        let request_builder = {\n            match request.method {\n                Method::Get => client.get(url),\n                Method::Post => {\n                    let mut client = client.post(url);\n                    match request.body {\n                        Some(RequestContent::Json(payload)) => client = client.json(&payload),\n                        Some(RequestContent::FormData(form)) => client = client.multipart(form),\n                        Some(RequestContent::FormUrlEncoded(payload)) => client = client.form(&payload),\n                        Some(RequestContent::Xml(payload)) => {\n                            let body = quick_xml::se::to_string(&payload)\n                                .change_context(ApiClientError::BodySerializationFailed)?;\n                            client = client.body(body).header(\"Content-Type\", \"application/xml\")\n                        }\n                        Some(RequestContent::RawBytes(payload)) => client = client.body(payload),\n                        None => {}\n                    }\n                    client\n                }\n                Method::Put => {\n                    let mut client = client.put(url);\n                    match request.body {\n                        Some(RequestContent::Json(payload)) => client = client.json(&payload),\n                        Some(RequestContent::FormData(form)) => client = client.multipart(form),\n                        Some(RequestContent::FormUrlEncoded(payload)) => client = client.form(&payload),\n                        Some(RequestContent::Xml(payload)) => {\n                            let body = quick_xml::se::to_string(&payload)\n                                .change_context(ApiClientError::BodySerializationFailed)?;\n                            client = client.body(body).header(\"Content-Type\", \"application/xml\")\n                        }\n                        Some(RequestContent::RawBytes(payload)) => client = client.body(payload),\n                        None => {}\n                    }\n                    client\n                }\n                Method::Delete => {\n                    let mut client = client.delete(url);\n                    match request.body {\n                        Some(RequestContent::Json(payload)) => client = client.json(&payload),\n                        Some(RequestContent::FormUrlEncoded(payload)) => client = client.form(&payload),\n                        Some(RequestContent::RawBytes(payload)) => client = client.body(payload),\n                        None => {}\n                        _ => {\n                            return Err(ApiClientError::UnexpectedState.into()).attach_printable(\n                                \"Only JSON, form URL encoded, and raw bytes are supported for DELETE requests\",\n                            )\n                        }\n                    }\n                    client\n                }\n                _ => {\n                    return Err(ApiClientError::UnexpectedState.into()).attach_printable(\n                        \"Unsupported HTTP method\",\n                    )\n                }\n            }\n        };\n\n        // Add default headers\n        let mut request_headers = request_builder.headers();\n\n        // Add X-HS-Latency header for performance tracking\n        if let Some(latency_value) = headers.get(X_HS_LATENCY) {\n  