    "content": "use std::collections::HashMap;\nuse serde_json::Value;\nuse error_stack::{ResultExt, Report};\nuse crate::errors::{RouterResponse, ApiErrorResponse};\n\n/// CRM Interface for tracking user activities\npub trait Crm: Send + Sync {\n    /// Track a production intent event for a merchant\n    ///\n    /// # Arguments\n    /// * `state` - Session state containing configuration\n    /// * `merchant_id` - The merchant ID for tracking\n    /// * `poc_email` - Point of contact email for the merchant\n    /// * `org_id` - Organization ID\n    /// * `metadata` - Additional metadata for tracking\n    ///\n    /// # Returns\n    /// * `RouterResponse<()>` - Result of the tracking operation\n    async fn track_prod_intent(\n        &self,\n        state: &crate::routes::SessionState,\n        merchant_id: &str,\n        poc_email: Option<&str>,\n        org_id: Option<&str>,\n        metadata: Option<HashMap<String, Value>>,\n    ) -> RouterResponse<()>;\n}\n\n/// No-op CRM implementation for when CRM tracking is disabled\n#[derive(Debug, Clone)]\npub struct NoCrm;\n\n#[async_trait::async_trait]\nimpl Crm for NoCrm {\n    async fn track_prod_intent(\n        &self,\n        _state: &crate::routes::SessionState,\n        _merchant_id: &str,\n        _poc_email: Option<&str>,\n        _org_id: Option<&str>,\n        _metadata: Option<HashMap<String, Value>>,\n    ) -> RouterResponse<()> {\n        Ok(crate::services::ApplicationResponse::StatusOk)\n    }\n}\n\n/// HubSpot CRM integration for tracking user activities\n#[derive(Debug, Clone)]\npub struct HubspotProxy {\n    /// HubSpot API endpoint for tracking\n    hubspot_url: String,\n    /// API key or token for HubSpot authentication\n    api_key: String,\n    /// Custom HTTP headers for the requests\n    headers: HashMap<String, String>,\n}\n\nimpl HubspotProxy {\n    /// Create a new HubSpot proxy instance\n    ///\n    /// # Arguments\n    /// * `hubspot_url` - HubSpot API endpoint URL\n    /// * `api_key` - HubSpot API key or OAuth token\n    /// * `headers` - Additional custom headers to include in requests\n    pub fn new(hubspot_url: String, api_key: String, headers: HashMap<String, String>) -> Self {\n        Self {\n            hubspot_url,\n            api_key,\n            headers,\n        }\n    }\n\n    /// Create a HubSpot proxy from configuration\n    ///\n    /// # Arguments\n    /// * `config` - Configuration containing HubSpot settings\n    /// * `state` - Session state for logging and error handling\n    pub fn from_config(\n        config: &crate::configs::settings::Settings,\n        _state: &crate::routes::SessionState,\n    ) -> Self {\n        let hubspot_url = config\n            .hubspot_config\n            .as_ref()\n            .and_then(|c| c.hubspot_url.clone())\n            .unwrap_or_else(|| \"https://api.hubspot.com\".to_string());\n\n        let api_key = config\n            .hubspot_config\n            .as_ref()\n            .and_then(|c| c.api_key.clone())\n            .unwrap_or_default();\n\n        let mut headers = HashMap::new();\n        if let Some(config_headers) = config.hubspot_config.as_ref().and_then(|c| c.headers.clone()) {\n            headers.extend(config_headers);\n        }\n\n        Self::new(hubspot_url, api_key, headers)\n    }\n\n    /// Make an HTTP request to HubSpot API\n    ///\n    /// # Arguments\n    /// * `state` - Session state for configuration\n    /// * `method` - HTTP method (GET, POST, etc.)\n    /// * `url` - API endpoint URL\n    /// * `body` - Optional request body\n    ///\n    /// # Returns\n    /// * `Result<reqwest::Response, Report<errors::ApiClientError>>` - HTTP response or error\n    async fn make_request(\n        &self,\n        state: &crate::routes::SessionState,\n        method: &str,\n        url: &str,\n        body: Option<String>,\n    ) -> Result<reqwest::Response, Report<crate::errors::ApiClientError>> {\n        use crate::services::external_http_client;\n        use common_utils::request::{Method, Request, RequestContent};\n\n        let request_method = match method {\n            \"GET\" => Method::Get,\n            \"POST\" => Method::Post,\n            \"PUT\" => Method::Put,\n            \"DELETE\" => Method::Delete,\n            _ => Method::Post,\n        };\n\n        let mut headers = std::collections::HashMap::new();\n        headers.insert(\"Authorization\".to_string(), format!(\"Bearer {}\", self.api_key));\n\n        // Add custom headers\n        for (key, value) in &self.headers {\n            headers.insert(key.clone(), value.clone());\n        }\n\n        let mut request = Request::new(request_method, url.to_string());\n        request.headers = headers;\n\n        if let Some(body_str) = body {\n            request.body = Some(RequestContent::RawBytes(body_str.into()));\n        }\n\n        external_http_client::send_request(state, request, None)\n            .await\n            .map_err(Report::new)\n    }\n\n    /// Send a tracking event to HubSpot\n    ///\n    /// # Arguments\n    /// * `state` - Session state for configuration and logging\n    /// * `event_name` - Name of the event to track\n    /// * `contact_email` - Email of the contact associated with the event\n    /// * `properties` - Event properties/attributes\n    ///\n    /// # Returns\n    /// * `RouterResponse<()>` - Result of the tracking operation\n    async fn send_hubspot_event(\n        &self,\n        state: &crate::routes::SessionState,\n        event_name: &str,\n        contact_email: &str,\n        properties: HashMap<String, Value>,\n    ) -> RouterResponse<()> {\n        if self.api_key.is_empty() {\n            return Err(ApiErrorResponse::InvalidData {\n                field: \"hubspot_api_key\".to_string(),\n                message: \"HubSpot API key is required\".to_string(),\n            }\n            .into());\n        }\n\n        let url = format!(\"{}/crm/v3/objects/contacts/search\", self.hubspot_url);\n\n        // Build the search request to find the contact by email\n        let search_request = serde_json::json!({\n            \"filterGroups\": [\n                {\n                    \"filters\": [\n                        {\n                            \"propertyName\": \"email\",\n                            \"operator\": \"EQ\",\n                            \"value\": contact_email\n                        }\n                    ]\n                }\n            ],\n            \"properties\": [\"firstname\", \"lastname\", \"company\"]\n        });\n\n        // First, try to find the contact\n        self.make_request(\n            state,\n            \"POST\",\n            &url,\n            Some(search_request.to_string()),\n        )\n        .await\n        .map_err(|_| {\n            ApiErrorResponse::ServerErrors(\n                vec![common_utils::errors::ApiErrorResponse::InternalServerError.into()].into()\n            )\n        })?;\n\n        // TODO: Parse the response to get contact ID\n        // For now, we'll just log the tracking event\n        router_env::logger::info!(\n            \"HubSpot tracking event - Event: {}, Contact: {}, Properties: {:?}\",\n            event_name,\n            contact_email,\n            properties\n        );\n\n        Ok(crate::services::ApplicationResponse::StatusOk)\n    }\n}\n\n#[async_trait::async_trait]\nimpl Crm for HubspotProxy {\n    async fn track_prod_intent(\n        &self,\n        state: &crate::routes::SessionState,\n        merchant_id: &str,\n        poc_email: Option<&str>,\n        org_id: Option<&str>,\n        metadata: Option<HashMap<String, Value>>,\n    ) -> RouterResponse<()> {\n        let contact_email = poc_email\n            .unwrap_or_else(|| format!(\"{}@{}\", merchant_id, org_id.unwrap_or(\"unknown\")).as_str());\n\n        let mut properties = HashMap::new();\n        properties.insert(\"merchant_id\".to_string(), merchant_id.into());\n\n        if let Some(org_id) = org_id {\n            properties.insert(\"organization_id\".to_string(), org_id.into());\n        }\n\n        if let Some(meta) = metadata {\n            for (key, value) in meta {\n                properties.insert(format!(\"metadata_{}\", key), value);\n            }\n        }\n\n        self.send_hubspot_event(state, \"prod_intent\", contact_email, properties)\n            .await\n    }\n}\n\n/// Factory function to create the appropriate CRM implementation\n///\n/// # Arguments\n/// * `config` - Configuration containing CRM settings\n/// * `state` - Session state for configuration\n///\n/// # Returns\n/// * Box<dyn Crm> - CRM implementation instance\npub fn create_crm(\n    config: &crate::configs::settings::Settings,\n    state: &crate::routes::SessionState,\n) -> Box<dyn Crm + Send + Sync> {\n    match &config.hubspot_config {\n        Some(hubspot_config) if hubspot_config.enabled {\n            Box::new(HubspotProxy::from_config(config, state))\n        }\n        _ => Box::new(NoCrm),\n    }\n}"
