pub async fn get_redis_data(
    state: SessionState,
    connector_customer_id: String,
    key_type: String,
) -> RouterResult<ApplicationResponse<RedisDataResponse>> {
    use crate::types::storage::revenue_recovery_redis_operation as redis_op;

    let redis_conn = state.store.get_redis_conn().change_context(
        errors::StorageError::RedisError(
            errors::RedisError::RedisConnectionError.into(),
        ),
    )?;

    let tokens_key = redis_op::RedisTokenManager::get_connector_customer_tokens_key(&connector_customer_id);
    let status_key = redis_op::RedisTokenManager::get_connector_customer_lock_key(&connector_customer_id);

    let data = match key_type.as_str() {
        "Tokens" => {
            // Get all tokens for the customer
            match redis_conn.get_hash_fields(&tokens_key.into()).await {
                Ok(hash_fields) => {
                    if hash_fields.is_empty() {
                        // No tokens found
                        return Err(errors::ApiErrorResponse::InvalidRequestData {
                            message: format!("Redis data not found for connector customer id:- '{}'", connector_customer_id),
                        }.into());
                    }
                    Some(serde_json::json!(hash_fields))
                }
                Err(_) => {
                    // No tokens found in Redis
                    return Err(errors::ApiErrorResponse::InvalidRequestData {
                        message: format!("Redis data not found for connector customer id:- '{}'", connector_customer_id),
                    }.into());
                }
            }
        }
        "Status" => {
            // Get status lock
            match redis_conn.get_key(&status_key.into()).await {
                Ok(Some(value)) => {
                    // Found status
                    Some(serde_json::json!(value))
                }
                Ok(None) => {
                    // No status found
                    return Err(errors::ApiErrorResponse::InvalidRequestData {
                        message: format!("Redis data not found for connector customer id:- '{}'", connector_customer_id),
                    }.into());
                }
                Err(_) => {
                    // Error getting status
                    return Err(errors::ApiErrorResponse::InvalidRequestData {
                        message: format!("Redis data not found for connector customer id:- '{}'", connector_customer_id),
                    }.into());
                }
            }
        }
        _ => {
            return Err(errors::ApiErrorResponse::InvalidRequestData {
                message: "Invalid key_type. Must be either 'Tokens' or 'Status'".to_string(),
            }.into());
        }
    };

    // Get TTL for the key (for Tokens key)
    let ttl_seconds = match key_type.as_str() {
        "Tokens" => {
            match redis_conn.get_key_ttl(&tokens_key.into()).await {
                Ok(ttl) => ttl as i64,
                Err(_) => -1, // Could not get TTL
            }
        }
        "Status" => {
            match redis_conn.get_key_ttl(&status_key.into()).await {
                Ok(ttl) => ttl as i64,
                Err(_) => -1, // Could not get TTL
            }
        }
        _ => -1,
    };

    let response = RedisDataResponse {
        exists: true,
        ttl_seconds,
        data,
    };

    Ok(ApplicationResponse::Json(response))
}

